//! The three files the identity is written as: the CSS custom properties every part of the app reads, the logo,
//! and the title card that opens the pitch.

use super::identity::{INK, Identity, PAPER};

/// `web/tokens/tokens.css`.
pub(crate) fn tokens_css(id: &Identity) -> String {
    let n = &id.neutral;
    let mut lines = vec![
        String::from(
            "/* firecal's identity. Generated by `cargo xtask tokens`: do not edit by hand.",
        ),
        String::from("   Where each number comes from: web/tokens/README.md. */"),
        String::from(":root {"),
        String::from("  color-scheme: light;"),
        String::new(),
        String::from("  /* Paper, ink, and the greys on the line between them. */"),
        format!("  --bg: {};", n.bg),
        format!("  --bg-deep: {};", n.bg_deep),
        format!("  --surface: {};", n.surface),
        format!("  --raised: {};", n.raised),
        format!("  --selection: {};", n.selection),
        format!("  --line: {};", n.line),
        format!("  --disabled: {};", n.disabled),
        format!("  --text-secondary: {};", n.text_secondary),
        format!("  --text: {};", n.text),
        format!("  --text-strong: {};", n.text_strong),
        String::new(),
        String::from(
            "  /* Colour only where it means something: activity, uncertainty, attention, healthy. */",
        ),
        format!("  --activity: {};", id.activity),
        format!("  --uncertainty: {};", id.uncertainty),
        format!("  --attention: {};", id.attention),
        format!("  --healthy: {};", id.healthy),
        format!("  --error: {};", id.error),
        format!("  --added: {};", id.added),
        String::new(),
        String::from(
            "  /* Calendar: --ramp-0 is a cell with no activity; 1 to 7 rise with it. A cell carries no text. */",
        ),
        format!("  --ramp-0: {};", id.empty_cell),
    ];
    lines.extend(
        (1..)
            .zip(&id.ramp)
            .map(|(step, colour)| format!("  --ramp-{step}: {colour};")),
    );
    lines.extend([
        String::new(),
        String::from(
            "  /* Marks that never rely on colour: the diamond (top right) is ink with a paper edge; a",
        ),
        String::from(
            "     provisional cell has a rose triangle with an ink edge in its bottom left corner,",
        ),
        String::from("     --provisional-size along each side. */"),
        format!("  --mark-fill: {INK};"),
        format!("  --mark-edge: {PAPER};"),
        format!("  --provisional-fill: {};", id.provisional_fill),
        format!("  --provisional-edge: {INK};"),
        String::from("  --provisional-size: 10px;"),
        format!("  --focus-ring: {INK};"),
    ]);
    lines.extend(SIZES.iter().copied().map(String::from));
    let [r, g, b] = INK.0;
    lines.push(format!(
        "  --shadow-float: 0 6px 20px rgba({r}, {g}, {b}, 0.12);"
    ));
    lines.extend(MOTION_AND_MEDIA.iter().copied().map(String::from));
    lines.join("\n") + "\n"
}

/// The tokens that are not colours: type, sizes and corners from `docs/style.md`.
const SIZES: [&str; 16] = [
    "",
    "  --font-ui: system-ui, -apple-system, \"SF Pro Text\", \"Segoe UI\", sans-serif;",
    "  --font-code: \"Monaspace Neon\", ui-monospace, \"Cascadia Mono\", Consolas, monospace;",
    "  --text-size-input: 17px;",
    "  --text-size-row: 14px;",
    "  --text-size-small: 12px;",
    "  --text-size-tiny: 11px;",
    "",
    "  --radius-panel: 10px;",
    "  --radius-row: 6px;",
    "  --radius-tag: 5px;",
    "  --hairline: 1px;",
    "  --field-height: 52px;",
    "  --row-height: 38px;",
    "  --icon-size: 24px;",
    "  --margin: 8px;",
];

/// The motion tokens, and what changes them on dense screens and for reduced motion.
const MOTION_AND_MEDIA: [&str; 16] = [
    "",
    "  --motion-duration: 280ms;",
    "  --motion-ease: cubic-bezier(0.2, 0.9, 0.3, 1.15);",
    "}",
    "",
    "@media (min-resolution: 2dppx) {",
    "  :root { --hairline: 0.5px; }",
    "}",
    "",
    "@media (min-resolution: 3dppx) {",
    "  :root { --hairline: 0.34px; }",
    "}",
    "",
    "@media (prefers-reduced-motion: reduce) {",
    "  :root { --motion-duration: 0ms; }",
    "}",
];

/// `web/tokens/logo.svg`: an ink arch with a terracotta circle under its round top, on a 32 grid.
pub(crate) fn logo_svg(id: &Identity) -> String {
    format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 32\" width=\"32\" height=\"32\">\
<title>firecal</title>\
<path fill=\"{INK}\" d=\"M5 31V15.5a11 11 0 0 1 22 0V31z\"/>\
<circle fill=\"{}\" cx=\"16\" cy=\"16\" r=\"6.5\"/>\
</svg>\n",
        id.activity
    )
}

/// `pitch/figures/title-card.svg`: the first slide, 1920 by 1080. The logo's arch and circle, large, beside the
/// name and one line; the shapes are the identity, and the words say what the project is.
pub(crate) fn title_card_svg(id: &Identity) -> String {
    let font = "system-ui, -apple-system, &quot;Segoe UI&quot;, sans-serif";
    format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 1920 1080\" width=\"1920\" height=\"1080\">\
<title>firecal: a burning-activity calendar from MODIS and VIIRS, harmonized</title>\
<rect width=\"1920\" height=\"1080\" fill=\"{PAPER}\"/>\
<path fill=\"{INK}\" d=\"M240 860V500a220 220 0 0 1 440 0V860z\"/>\
<circle fill=\"{activity}\" cx=\"460\" cy=\"520\" r=\"130\"/>\
<text x=\"800\" y=\"520\" font-family=\"{font}\" font-size=\"132\" font-weight=\"600\" fill=\"{INK}\">firecal</text>\
<text x=\"804\" y=\"600\" font-family=\"{font}\" font-size=\"40\" fill=\"{text}\">\
A burning-activity calendar from MODIS and VIIRS, harmonized.</text>\
<text x=\"804\" y=\"860\" font-family=\"{font}\" font-size=\"28\" fill=\"{secondary}\">\
NASA Space Apps 2026 · Harmonization of MODIS and VIIRS Hot Spots</text>\
</svg>\n",
        activity = id.activity,
        text = id.neutral.text,
        secondary = id.neutral.text_secondary,
    )
}
